import '../../../../../../Core/Models/all_categories.dart';class AllCategoriesEntities extends AllCategories {  AllCategoriesEntities({    required super.id,    required super.name,    required super.createdAt,    required super.updatedAt,    required super.parentId,  }) ;  factory AllCategoriesEntities.fromCategories(AllCategories product) {    return AllCategoriesEntities(      id: product.id,      name: product.name,      createdAt: product.createdAt,      updatedAt: product.updatedAt,      parentId: product.parentId,    );  }  Map<String, dynamic> toMap() {    return {      'id': id,      'name': name,      'parent_id': parentId,      'created_at': createdAt?.toIso8601String(),      'updated_at': updatedAt?.toIso8601String(),    };  }}